import{_ as h,o as a,c as s,a3 as n}from"./chunks/framework.Q4yG9rk_.js";const c=JSON.parse('{"title":"尚书","description":"儒家五经之一：上古政教文告汇编，五十八篇，读中国政治观念的源头。","frontmatter":{"title":"尚书","description":"儒家五经之一：上古政教文告汇编，五十八篇，读中国政治观念的源头。","category":"guide","aliases":["尚书","书经","书","shangshu","尚书篇章","尚书目录"],"source":["《尚书》"],"outline":[2,3]},"headers":[],"relativePath":"lizhimingde/sishu-wujing/shangshu/index.md","filePath":"lizhimingde/sishu-wujing/shangshu/index.md","lastUpdated":1789987057000}'),l={name:"lizhimingde/sishu-wujing/shangshu/index.md"};function e(g,i,u,r,t,o){return a(),s("div",null,[...i[0]||(i[0]=[n('<h1 id="尚书" tabindex="-1">尚书 <a class="header-anchor" href="#尚书" aria-label="Permalink to &quot;尚书&quot;">​</a></h1><p>《尚书》又单称《书》，汉代尊为《书经》，是现存最早的一部政教文献汇编——上起尧舜，下至秦穆公。<strong>它记录的不是故事，是「话」</strong>：誓词、诰命、训诫、政令。</p><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><ul><li><strong>体例</strong>：典、谟、训、诰、誓、命六体。「典」记制度（尧典、舜典），「谟」记谋议（皋陶谟），「诰」是君王训诫臣民，「誓」是战前誓师，「命」是册命。</li><li><strong>分部</strong>：按时代分<strong>虞书、夏书、商书、周书</strong>四部分。</li><li><strong>真伪问题</strong>（读《尚书》绕不开的一层）：今文《尚书》二十八篇为汉代伏生所传，是可靠底本；另有「古文尚书」二十五篇，自宋代起被疑，至清代阎若璩《尚书古文疏证》考定为后人伪作。今通行的五十八篇是二者合编的结果——<strong>读时要分清哪一篇出自哪一层</strong>。</li></ul><h2 id="为什么重要" tabindex="-1">为什么重要 <a class="header-anchor" href="#为什么重要" aria-label="Permalink to &quot;为什么重要&quot;">​</a></h2><ul><li><strong>中国政治观念的源头</strong>：天命、德治、民本、慎罚——这些词的第一次成形都在这里。</li><li><strong>《禹贡》是中国最早的地理文献</strong>：九州、山川、贡赋的完整书写。</li><li><strong>《洪范》是政治哲学的纲领</strong>：九畴之说，后世论治国多取于此。</li><li><strong>语汇出典</strong>：满招损谦受益、玩物丧志、有备无患、功亏一篑、人心惟危道心惟微——都出自《尚书》。</li></ul><h2 id="怎么读" tabindex="-1">怎么读 <a class="header-anchor" href="#怎么读" aria-label="Permalink to &quot;怎么读&quot;">​</a></h2><ol><li><strong>先读今文二十八篇</strong>，它们最可靠，也最能代表《尚书》的原貌；</li><li><strong>《尧典》《舜典》《皋陶谟》</strong> 看上古政治的德治理想；<strong>《禹贡》</strong> 看地理格局；<strong>《洪范》</strong> 看政治哲学纲领；</li><li><strong>《酒诰》《无逸》《康诰》</strong> 是周公对殷遗民与周室子弟的训诫，最能看出周初的政治焦虑；</li><li><strong>《秦誓》</strong> 为末篇，收在秦穆公悔过之言上，颇有意味；</li><li><strong>注本</strong>：可参考孙星衍《尚书今古文注疏》、屈万里《尚书今注今译》。</li><li><strong>读法提醒</strong>：《尚书》文字古奥（韩愈称「周诰殷盘，诘屈聱牙」），不必强求逐字通读，先取几篇熟读即可。</li></ol><h2 id="篇章" tabindex="-1">篇章 <a class="header-anchor" href="#篇章" aria-label="Permalink to &quot;篇章&quot;">​</a></h2><p>一篇一页，共 <strong>58 页</strong>（虞书 5 · 夏书 4 · 商书 17 · 周书 32）。</p><ol><li><a href="/Dao/lizhimingde/sishu-wujing/shangshu/chapter-01">尧典</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/shangshu/chapter-02">舜典</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/shangshu/chapter-03">大禹谟</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/shangshu/chapter-04">皋陶谟</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/shangshu/chapter-05">益稷</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/shangshu/chapter-06">禹贡</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/shangshu/chapter-07">甘誓</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/shangshu/chapter-08">五子之歌</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/shangshu/chapter-09">胤征</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/shangshu/chapter-10">汤誓</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/shangshu/chapter-11">仲虺之诰</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/shangshu/chapter-12">汤诰</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/shangshu/chapter-13">伊训</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/shangshu/chapter-14">太甲上</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/shangshu/chapter-15">太甲中</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/shangshu/chapter-16">太甲下</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/shangshu/chapter-17">咸有一德</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/shangshu/chapter-18">盘庚上</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/shangshu/chapter-19">盘庚中</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/shangshu/chapter-20">盘庚下</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/shangshu/chapter-21">说命上</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/shangshu/chapter-22">说命中</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/shangshu/chapter-23">说命下</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/shangshu/chapter-24">高宗肜日</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/shangshu/chapter-25">西伯戡黎</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/shangshu/chapter-26">微子</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/shangshu/chapter-27">泰誓上</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/shangshu/chapter-28">泰誓中</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/shangshu/chapter-29">泰誓下</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/shangshu/chapter-30">牧誓</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/shangshu/chapter-31">武成</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/shangshu/chapter-32">洪范</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/shangshu/chapter-33">旅獒</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/shangshu/chapter-34">金縢</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/shangshu/chapter-35">大诰</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/shangshu/chapter-36">微子之命</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/shangshu/chapter-37">康诰</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/shangshu/chapter-38">酒诰</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/shangshu/chapter-39">梓材</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/shangshu/chapter-40">召诰</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/shangshu/chapter-41">洛诰</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/shangshu/chapter-42">多士</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/shangshu/chapter-43">无逸</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/shangshu/chapter-44">君奭</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/shangshu/chapter-45">蔡仲之命</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/shangshu/chapter-46">多方</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/shangshu/chapter-47">立政</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/shangshu/chapter-48">周官</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/shangshu/chapter-49">君陈</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/shangshu/chapter-50">顾命</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/shangshu/chapter-51">康王之诰</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/shangshu/chapter-52">毕命</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/shangshu/chapter-53">君牙</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/shangshu/chapter-54">冏命</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/shangshu/chapter-55">吕刑</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/shangshu/chapter-56">文侯之命</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/shangshu/chapter-57">费誓</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/shangshu/chapter-58">秦誓</a></li></ol><h3 id="说明" tabindex="-1">说明 <a class="header-anchor" href="#说明" aria-label="Permalink to &quot;说明&quot;">​</a></h3><ul><li>各章页当前为骨架（篇名、位置、待整理标记），<strong>原文转录、字词释义与逐章解读后续分批推进</strong>。</li><li>整理方式与《道德经》一致：<strong>一章一页</strong>，目录与文件一一对应。</li><li>参考：孙星衍《尚书今古文注疏》、屈万里《尚书今注今译》</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>同栏目：<a href="/Dao/lizhimingde/sishu-wujing/shijing/">诗经</a> · <a href="/Dao/lizhimingde/sishu-wujing/liji/">礼记</a> · <a href="/Dao/lizhimingde/sishu-wujing/chunqiu/">春秋</a> · <a href="/Dao/lizhimingde/sishu-wujing/yijing">周易</a></li><li>入其门的次第：见<a href="/Dao/lizhimingde/sishu-wujing/">四书五经总览</a></li></ul>',15)])])}const m=h(l,[["render",e]]);export{c as __pageData,m as default};
